import { useState } from "react";

export type Props = { onRecord: (value: number) => void };

export function Component({ onRecord }: Props) {
  const [reading, setReading] = useState("");
  const [history, setHistory] = useState<number[]>([]);
  const [hasError, setHasError] = useState(false);

  function record() {
    const text = reading.trim();
    const value = Number(text);
    if (!/^-?[0-9]+$/.test(text) || !Number.isSafeInteger(value)) {
      setHasError(true);
      return;
    }
    setHistory((previous) => [...previous, value]);
    setReading("");
    setHasError(false);
    onRecord(value);
  }

  function clear() {
    setHistory([]);
    setReading("");
    setHasError(false);
  }

  return (
    <div
      data-testid="panel"
      style={{
        background: "#eef4ff",
        color: "#17345c",
        padding: "12px",
        gap: "6px",
        display: "grid",
      }}
    >
      <label>
        Reading
        <input
          type="text"
          value={reading}
          onChange={(event) => setReading(event.currentTarget.value)}
        />
      </label>
      <button type="button" onClick={record}>Record</button>
      <button type="button" onClick={clear}>Clear</button>
      {hasError && <p role="alert">Invalid reading</p>}
      <output aria-label="Latest">
        {history.length === 0 ? "None" : history[history.length - 1]}
      </output>
      <ul aria-label="History">
        {history.map((value, index) => <li key={index}>{value}</li>)}
      </ul>
    </div>
  );
}
